CREATE OR REPLACE FUNCTION public.validate_card_location() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.lists WHERE id=NEW.list_id AND board_id=NEW.board_id) THEN RAISE EXCEPTION 'List does not belong to destination board'; END IF; IF TG_TABLE_NAME='card_mirrors' THEN IF TG_OP='UPDATE' THEN IF NEW.card_id<>OLD.card_id THEN RAISE EXCEPTION 'A mirror cannot change its source card'; END IF; END IF; ELSE IF TG_OP='UPDATE' THEN IF NEW.board_id<>OLD.board_id THEN IF NOT public.owns_board(OLD.board_id) OR NOT public.can_access_board(NEW.board_id) THEN RAISE EXCEPTION 'Only the source board owner can move a card between boards'; END IF; END IF; END IF; END IF; RETURN NEW; END $$;